    "contextName": "ГЕН ЯРОСТИ",
    "description": "Нанесение или получение урона генерирует ярость. При достижении максимального уровня ярости способности Гнара изменятся, и его следующая способность превратит его в Мега Гнара на 15 секунд.\nМини-Гнар: увеличивает скорость передвижения (максимум 20), дальность атаки (максимум 150) и скорость атаки (максимум 90%).\nМега Гнар: получает 100 здоровья (максимум 900), базовую броню 5 (максимум 60), базовое сопротивление магии 5 (максимум 70) и базовую силу атаки 8 (максимум 50).\nПри нанесении или получении урона в роли Мини-Гнара ярость увеличивается на 3 на следующие 2 секунды. Атака вражеских чемпионов генерирует 2 ярости, а атака не-чемпионов генерирует 1 ярость. При максимальной ярости Гнар автоматически трансформируется через 4 секунды, если не использует способность.\nЯрость угасает через 13 секунд, если Гнар за это время не нанес или не получил урона. Гнар не может генерировать ярость в течение 15 секунд после того, как он снова превратится из Мини-Гнара в Мега-Гнара.\nМини-Гнар и Мега-Гнар имеют общее время восстановления всех способностей, кроме Гипера.",
