    "description": "Отмечает цели Меткой Сородича для охоты. Наносит дополнительно 30% урона отмеченным маленьким монстрам, красным ежевикам и синим стражам. Есть разные способы отметить цель:\n1. Автоматическое обновление: каждые 25 секунд срок действия метки на монстре истекает, и автоматически применяется новая. На миникарте подсвечиваются отметки на монстрах.\n2. Активно: нажмите кнопку «Отметить» над своими заклинаниями, чтобы отметить вражеского чемпиона. Время восстановления 40 секунд (время восстановления 120 секунд для маркировки того же чемпиона).\nУничтожение преследуемой цели дает эффект Знака Сородича, который усиливает Сородича. Первые 3 полученных стека дают дальность атаки 75, а каждые 3 полученных стака впоследствии увеличивают дальность атаки 25.\nЗнак Сородича также усиливает способности и дает им следующие эффекты:\n«Танец стрел»: дополнительная скорость атаки увеличивается на 0% (5% от количества стеков «Знак сородича»).\nВолчье бешенство: наносит дополнительный урон, равный 0% от текущего здоровья (1% от количества стеков «Знак сородича»).\nНарастающий ужас: наносит дополнительный урон, равный 0% от недостающего здоровья (1% от количества стаков «Знак сородича»).",
