    "description": "Теневой убийца: Каин Теневой Убийца сражается с Раастом Убийцей Даркинов за контроль.\nНанесение урона чемпионам дальнего боя заряжает Теневого убийцу, а нанесение урона чемпионам ближнего боя заряжает Убийцу даркинов. При полном заряде Каин может навсегда трансформироваться на своей базе.\nТеневой убийца: атаки и способности наносят дополнительный магический урон от 52% до 66% в течение 3 секунд. Это происходит только в том случае, если Каин находился вне боя в течение 6 секунд или использовал Umbral Trespass.\n\nРааст: Каин Теневой Убийца сражается с Раастом Убийцей Даркинов за контроль.\nЧемпионы дальнего боя, наносящие урон, атакуют Теневого Убийцы, а чемпионы ближнего боя, наносящие урон, атакуют Убийцу Даркинов. При полном заряде Каин может навсегда трансформироваться на своей базе.\nУбийца Даркинов: Каин исцеляет 24% - 38% от физического урона, нанесенного чемпионам.\nПерезарядка Рааста: — с.",
