    "description": "Перемещение, атака и применение заклинаний создают стеки энергии. При суммировании 100 ваша следующая атака исцеляет вас, увеличивает скорость передвижения и восстанавливает ману или энергию, если вы атакуете чемпиона. При накоплении энергии 100 ваша следующая атака увеличивает скорость атаки на 40%.\nЛечение: 15 - 110 + 15% дополнительной силы атаки + 10% силы умений.\nБонус к скорости передвижения: 20% за 1 секунду.\nАтакуя чемпиона, восстанавливайте 8% недостающей маны или 8% недостающей энергии.\nИсцеляет на 35% (ближний бой) / 15% (дальний бой) при атаке миньонов или монстров.",
